/*
SKILLSWAP DBMS ASSIGNMENT - COMPLETE FRESH DATABASE SCRIPT
Database: skillswap_final | MySQL 8.0.31+ (tested design for MySQL 8.0.46)

WARNING: This script drops ONLY skillswap_final before rebuilding it.
It does not touch skillswap_final. Run this script in MySQL Workbench.
The generated demo accounts use placeholder password hashes and are not login-ready.
*/

DROP DATABASE IF EXISTS skillswap_final;
CREATE DATABASE skillswap_final;
USE skillswap_final;

-- =========================================================
-- 0. CREATE ALL SEVEN APPLICATION TABLES (DDL)
-- =========================================================

CREATE TABLE users (
    user_id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    contact VARCHAR(30),
    degree VARCHAR(100),
    country VARCHAR(100),
    state VARCHAR(100),
    city VARCHAR(100),
    coins INT NOT NULL DEFAULT 100,
    CHECK (coins >= 0)
) ENGINE=InnoDB;

CREATE TABLE skills (
    skill_id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE,
    category VARCHAR(100)
) ENGINE=InnoDB;

CREATE TABLE skill_offering (
    offering_id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    skill_id INT NOT NULL,
    proficiency_level VARCHAR(50),
    CONSTRAINT fk_offering_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_offering_skill FOREIGN KEY (skill_id)
        REFERENCES skills(skill_id) ON DELETE CASCADE,
    CONSTRAINT uq_offering_user_skill UNIQUE (user_id, skill_id)
) ENGINE=InnoDB;

CREATE TABLE skill_interest (
    interest_id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    skill_id INT NOT NULL,
    desired_level VARCHAR(50),
    CONSTRAINT fk_interest_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_interest_skill FOREIGN KEY (skill_id)
        REFERENCES skills(skill_id) ON DELETE CASCADE,
    CONSTRAINT uq_interest_user_skill UNIQUE (user_id, skill_id)
) ENGINE=InnoDB;

CREATE TABLE match_record (
    match_id INT AUTO_INCREMENT PRIMARY KEY,
    requester_id INT NOT NULL,
    recipient_id INT NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'pending',
    match_score DECIMAL(5,2) NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_match_requester FOREIGN KEY (requester_id) REFERENCES users(user_id),
    CONSTRAINT fk_match_recipient FOREIGN KEY (recipient_id) REFERENCES users(user_id),
    CONSTRAINT chk_match_different_users CHECK (requester_id <> recipient_id),
    CONSTRAINT chk_match_score CHECK (match_score BETWEEN 0 AND 100)
) ENGINE=InnoDB;

CREATE TABLE session_request (
    request_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    requester_id INT NOT NULL,
    recipient_id INT NOT NULL,
    skill_id INT NOT NULL,
    session_type VARCHAR(30) NOT NULL DEFAULT 'online',
    status VARCHAR(30) NOT NULL DEFAULT 'pending',
    requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    duration INT,
    coins_earned INT NOT NULL DEFAULT 0,
    CONSTRAINT fk_session_requester FOREIGN KEY (requester_id) REFERENCES users(user_id),
    CONSTRAINT fk_session_recipient FOREIGN KEY (recipient_id) REFERENCES users(user_id),
    CONSTRAINT fk_session_skill FOREIGN KEY (skill_id) REFERENCES skills(skill_id),
    CONSTRAINT chk_session_different_users CHECK (requester_id <> recipient_id),
    CONSTRAINT chk_session_duration CHECK (duration IS NULL OR duration >= 0),
    CONSTRAINT chk_session_coins CHECK (coins_earned >= 0)
) ENGINE=InnoDB;

CREATE TABLE messages (
    message_id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sender_id INT NOT NULL,
    receiver_id INT NOT NULL,
    message_text TEXT NOT NULL,
    sent_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_read TINYINT(1) NOT NULL DEFAULT 0,
    CONSTRAINT fk_message_sender FOREIGN KEY (sender_id) REFERENCES users(user_id),
    CONSTRAINT fk_message_receiver FOREIGN KEY (receiver_id) REFERENCES users(user_id)
) ENGINE=InnoDB;

