-- All seven tables now contain 10,100 rows in total.\n\n\n-- =========================================================
-- 1. DATABASE AND TABLE VERIFICATION
-- =========================================================

SELECT VERSION() AS mysql_version;
SHOW TABLES;

DESCRIBE users;
DESCRIBE skills;
DESCRIBE skill_offering;
DESCRIBE skill_interest;
DESCRIBE match_record;
DESCRIBE session_request;
DESCRIBE messages;

-- Total records in all project tables
SELECT 'users' AS table_name, COUNT(*) AS total_records FROM users
UNION ALL
SELECT 'skills', COUNT(*) FROM skills
UNION ALL
SELECT 'skill_offering', COUNT(*) FROM skill_offering
UNION ALL
SELECT 'skill_interest', COUNT(*) FROM skill_interest
UNION ALL
SELECT 'match_record', COUNT(*) FROM match_record
UNION ALL
SELECT 'session_request', COUNT(*) FROM session_request
UNION ALL
SELECT 'messages', COUNT(*) FROM messages;

-- Verify foreign-key relationships
SELECT TABLE_NAME, COLUMN_NAME, CONSTRAINT_NAME,
       REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME
FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE
WHERE TABLE_SCHEMA = 'skillswap_final'
  AND REFERENCED_TABLE_NAME IS NOT NULL
ORDER BY TABLE_NAME;

-- Verify constraints
SELECT TABLE_NAME, CONSTRAINT_NAME, CONSTRAINT_TYPE
FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS
WHERE TABLE_SCHEMA = 'skillswap_final'
ORDER BY TABLE_NAME, CONSTRAINT_TYPE;

-- Verify CHECK constraints
SELECT tc.TABLE_NAME, cc.CONSTRAINT_NAME, cc.CHECK_CLAUSE
FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
JOIN INFORMATION_SCHEMA.CHECK_CONSTRAINTS cc
  ON tc.CONSTRAINT_SCHEMA = cc.CONSTRAINT_SCHEMA
 AND tc.CONSTRAINT_NAME = cc.CONSTRAINT_NAME
WHERE tc.TABLE_SCHEMA = 'skillswap_final'
  AND tc.CONSTRAINT_TYPE = 'CHECK';

-- Verify UNIQUE constraints
SELECT TABLE_NAME, INDEX_NAME,
       GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns_name
FROM INFORMATION_SCHEMA.STATISTICS
WHERE TABLE_SCHEMA = 'skillswap_final'
  AND NON_UNIQUE = 0
  AND INDEX_NAME <> 'PRIMARY'
GROUP BY TABLE_NAME, INDEX_NAME;

-- Verify NOT NULL and DEFAULT constraints
SELECT TABLE_NAME, COLUMN_NAME, IS_NULLABLE, COLUMN_DEFAULT,
       COLUMN_TYPE, EXTRA
FROM INFORMATION_SCHEMA.COLUMNS
WHERE TABLE_SCHEMA = 'skillswap_final'
ORDER BY TABLE_NAME, ORDINAL_POSITION;

-- =========================================================
-- 2. DDL (CREATE, ALTER, TRUNCATE, DROP) DEMONSTRATION
-- =========================================================

-- CREATE TABLE
CREATE TABLE ddl_demo (
    demo_id INT PRIMARY KEY AUTO_INCREMENT,
    demo_name VARCHAR(100) NOT NULL,
    amount INT DEFAULT 0
);

-- ALTER TABLE: add a column
ALTER TABLE ddl_demo
ADD COLUMN category VARCHAR(50);

-- INSERT sample rows into the demo table
INSERT INTO ddl_demo (demo_name, amount, category)
VALUES
('SQL Practice', 100, 'Database'),
('Web Development', 200, 'Programming');

DESCRIBE ddl_demo;
SELECT * FROM ddl_demo;

-- TRUNCATE demonstration
CREATE TABLE truncate_demo (
    id INT PRIMARY KEY,
    name VARCHAR(50)
);

INSERT INTO truncate_demo VALUES
(1, 'Demo One'),
(2, 'Demo Two');

TRUNCATE TABLE truncate_demo;
SELECT * FROM truncate_demo;

-- DROP demonstration (only the two demo tables)
DROP TABLE truncate_demo;
DROP TABLE ddl_demo;

-- =========================================================
-- 3. DML AND TRANSACTION (INSERT, UPDATE, DELETE, ROLLBACK)
-- =========================================================

START TRANSACTION;

-- INSERT a temporary message
INSERT INTO messages (sender_id, receiver_id, message_text)
VALUES (1, 2, 'This is a temporary SQL assignment message');

SET @test_message_id = LAST_INSERT_ID();

SELECT *
FROM messages
WHERE message_id = @test_message_id;

-- UPDATE the temporary message
UPDATE messages
SET message_text = 'Message updated for SQL assignment'
WHERE message_id = @test_message_id;

SELECT *
FROM messages
WHERE message_id = @test_message_id;

-- DELETE the temporary message
DELETE FROM messages
WHERE message_id = @test_message_id;

SELECT *
FROM messages
WHERE message_id = @test_message_id;

-- Undo the INSERT, UPDATE and DELETE demonstration
ROLLBACK;

-- Verify the original data remains
SELECT COUNT(*) AS total_messages
FROM messages;

-- =========================================================
-- 4. SQL OPERATORS
-- =========================================================

-- 4.1 Arithmetic operators
SELECT username, coins, coins + 50 AS updated_coins
FROM users;

SELECT username, coins, coins * 2 AS double_coins
FROM users;

-- 4.2 Comparison operators
SELECT *
FROM users
WHERE coins > 100;

SELECT *
FROM session_request
WHERE status = 'accepted';

-- 4.3 Logical operators
SELECT *
FROM users
WHERE country = 'India' AND coins >= 100;

SELECT *
FROM session_request
WHERE status = 'pending' OR status = 'accepted';

-- 4.4 IN and NOT IN
SELECT *
FROM session_request
WHERE status IN ('pending', 'accepted');

SELECT *
FROM session_request
WHERE status NOT IN ('pending', 'ended');

SELECT user_id, username, coins
FROM users
WHERE coins IN (50, 100, 150);

SELECT skill_id, name, category
FROM skills
WHERE category NOT IN ('Programming', 'Design');

-- 4.5 BETWEEN
SELECT *
FROM session_request
WHERE duration BETWEEN 30 AND 60;

SELECT *
FROM users
WHERE coins BETWEEN 100 AND 500;

-- 4.6 LIKE
SELECT *
FROM skills
WHERE name LIKE 'A%';

SELECT *
FROM skills
WHERE name LIKE '%Java%';

-- 4.7 IS NULL
SELECT *
FROM users
WHERE city IS NULL;

SELECT *
FROM skills
WHERE category IS NULL;

-- 4.8 EXISTS
SELECT *
FROM users u
WHERE EXISTS (
    SELECT 1
    FROM skill_offering so
    WHERE so.user_id = u.user_id
);

SELECT *
FROM users u
WHERE EXISTS (
    SELECT 1
    FROM messages m
    WHERE m.sender_id = u.user_id
);

-- =========================================================
-- 5. AGGREGATE FUNCTIONS
-- =========================================================

-- COUNT
SELECT COUNT(*) AS total_users FROM users;
SELECT COUNT(*) AS total_offerings FROM skill_offering;

-- SUM
SELECT SUM(coins) AS total_coins FROM users;
SELECT SUM(coins_earned) AS total_coins_earned FROM session_request;

-- AVG
SELECT AVG(coins) AS average_coins FROM users;
SELECT AVG(duration) AS average_duration FROM session_request;

-- MIN
SELECT MIN(coins) AS minimum_coins FROM users;
SELECT MIN(duration) AS minimum_duration FROM session_request;

-- MAX
SELECT MAX(coins) AS maximum_coins FROM users;
SELECT MAX(duration) AS maximum_duration FROM session_request;

-- GROUP BY
SELECT status, COUNT(*) AS total_requests
FROM session_request
GROUP BY status;

SELECT s.name, COUNT(so.offering_id) AS total_offerings
FROM skills s
JOIN skill_offering so ON s.skill_id = so.skill_id
GROUP BY s.skill_id, s.name
ORDER BY total_offerings DESC;

-- =========================================================
-- 6. BUILT-IN, NUMERIC, DATE/TIME AND STRING FUNCTIONS
-- =========================================================

-- 6.1 Numeric functions
SELECT ROUND(AVG(coins), 2) AS rounded_average_coins
FROM users;

SELECT ABS(MIN(coins) - MAX(coins)) AS coin_difference
FROM users;

SELECT ROUND(AVG(match_score), 1) AS average_match_score
FROM match_record;

SELECT ABS(MIN(coins) - AVG(coins)) AS coin_difference
FROM users;

-- 6.2 Date and time functions
SELECT NOW() AS current_datetime;

SELECT YEAR(requested_at) AS request_year
FROM session_request
LIMIT 5;

SELECT MONTH(requested_at) AS request_month
FROM session_request
LIMIT 5;

-- 6.3 String functions: CONCAT, UPPER, LOWER, LENGTH, SUBSTRING, TRIM
SELECT CONCAT(username, ' - ', email) AS user_details
FROM users
LIMIT 5;

SELECT UPPER(name) AS uppercase_name
FROM skills
LIMIT 5;

SELECT LOWER(name) AS lowercase_name
FROM skills
LIMIT 5;

SELECT name, LENGTH(name) AS name_length
FROM skills
LIMIT 5;

SELECT SUBSTRING(name, 1, 3) AS short_name
FROM skills
LIMIT 5;

SELECT TRIM('   Skill Swap   ') AS trimmed_text;

SELECT LENGTH('   Database   ') AS original_length,
       LENGTH(TRIM('   Database   ')) AS trimmed_length;

-- =========================================================
-- 7. SET OPERATIONS
-- =========================================================

-- UNION: distinct user IDs
SELECT user_id FROM skill_offering
UNION
SELECT user_id FROM skill_interest;

SELECT requester_id AS user_id FROM session_request
UNION
SELECT recipient_id AS user_id FROM session_request;

-- UNION ALL: includes duplicates
SELECT user_id FROM skill_offering
UNION ALL
SELECT user_id FROM skill_interest;

SELECT requester_id AS user_id FROM session_request
UNION ALL
SELECT recipient_id AS user_id FROM session_request;

-- INTERSECT: users who both offer and want skills
SELECT user_id FROM skill_offering
INTERSECT
SELECT user_id FROM skill_interest;

-- EXCEPT: users who offer skills but do not want any skills
SELECT user_id FROM skill_offering
EXCEPT
SELECT user_id FROM skill_interest;

-- =========================================================
-- 8. SUBQUERIES
-- =========================================================

-- 8.1 Simple subqueries

-- 8.1.1 Users having more coins than the average coins
SELECT user_id, username, coins
FROM users
WHERE coins > (
    SELECT AVG(coins)
    FROM users
);

-- 8.1.2 Skills that have at least one skill offering
SELECT skill_id, name
FROM skills
WHERE skill_id IN (
    SELECT skill_id
    FROM skill_offering
);

-- 8.2 Nested subqueries

-- 8.2.1 Users whose coins are greater than the average coins
-- of users who have offered skills
SELECT user_id, username, coins
FROM users
WHERE coins > (
    SELECT AVG(coins)
    FROM users
    WHERE user_id IN (
        SELECT user_id
        FROM skill_offering
    )
);

-- 8.2.2 Skills offered by users whose coins exceed the overall average
SELECT skill_id, name
FROM skills
WHERE skill_id IN (
    SELECT skill_id
    FROM skill_offering
    WHERE user_id IN (
        SELECT user_id
        FROM users
        WHERE coins > (
            SELECT AVG(coins)
            FROM users
        )
    )
);

-- 8.3 Correlated subqueries

-- 8.3.1 Users having more coins than the average coins
-- of users from the same city
SELECT u.user_id, u.username, u.city, u.coins
FROM users u
WHERE u.coins > (
    SELECT AVG(u2.coins)
    FROM users u2
    WHERE u2.city = u.city
);

-- 8.3.2 Skills that have more than 20 offerings
SELECT s.skill_id, s.name
FROM skills s
WHERE (
    SELECT COUNT(*)
    FROM skill_offering so
    WHERE so.skill_id = s.skill_id
) > 20;

-- =========================================================
-- 9. PROCEDURAL SQL: STORED PROCEDURE, FUNCTION, TRIGGER
-- =========================================================

-- Stored procedure
DROP PROCEDURE IF EXISTS GetUserSkills;

DELIMITER $$
CREATE PROCEDURE GetUserSkills(IN p_user_id INT)
BEGIN
    SELECT u.username, s.name AS skill_name, so.proficiency_level
    FROM users u
    JOIN skill_offering so ON u.user_id = so.user_id
    JOIN skills s ON so.skill_id = s.skill_id
    WHERE u.user_id = p_user_id;
END $$
DELIMITER ;

CALL GetUserSkills(1);

-- Stored function
DROP FUNCTION IF EXISTS CountUserSkills;

DELIMITER $$
CREATE FUNCTION CountUserSkills(p_user_id INT)
RETURNS INT
DETERMINISTIC
READS SQL DATA
BEGIN
    DECLARE total_skills INT;

    SELECT COUNT(*)
    INTO total_skills
    FROM skill_offering
    WHERE user_id = p_user_id;

    RETURN total_skills;
END $$
DELIMITER ;

SELECT CountUserSkills(1) AS total_skills;

-- Trigger demonstration using a separate demo table
DROP TRIGGER IF EXISTS BeforeTriggerDemoInsert;
DROP TABLE IF EXISTS trigger_demo;

CREATE TABLE trigger_demo (
    id INT AUTO_INCREMENT PRIMARY KEY,
    message VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

DELIMITER $$
CREATE TRIGGER BeforeTriggerDemoInsert
BEFORE INSERT ON trigger_demo
FOR EACH ROW
BEGIN
    SET NEW.message = UPPER(NEW.message);
END $$
DELIMITER ;

INSERT INTO trigger_demo(message)
VALUES ('hello skillswap');

SELECT * FROM trigger_demo;

-- Clean up only the trigger demonstration objects
DROP TRIGGER IF EXISTS BeforeTriggerDemoInsert;
DROP TABLE IF EXISTS trigger_demo;

