CREATE USER 'skillswap_demo'@'localhost'
IDENTIFIED BY 'SkillSwap@2026';

GRANT SELECT ON skillswap_final.skills
TO 'skillswap_demo'@'localhost';

SHOW GRANTS FOR 'skillswap_demo'@'localhost';

REVOKE SELECT ON skillswap_final.skills
FROM 'skillswap_demo'@'localhost';

SHOW GRANTS FOR 'skillswap_demo'@'localhost';

-- Remove the temporary demonstration account
